// Msgsize returns an upper bound estimate of the number of bytes occupied by the serialized message
func (z *NES) Msgsize() (s int) {
	s = 1 + 8 + msgp.IntSize + 4
	if z.CPU == nil {
		s += msgp.NilSize
	} else {
		s += z.CPU.Msgsize()
	}
	s += 4 + msgp.ArrayHeaderSize + (0x800 * (msgp.Uint8Size)) + 4
	if z.PPU == nil {
		s += msgp.NilSize
	} else {
		s += z.PPU.Msgsize()
	}
	s += 4
	if z.APU == nil {
		s += msgp.NilSize
	} else {
		s += z.APU.Msgsize()
	}
	s += 6
	if z.Mixer == nil {
		s += msgp.NilSize
	} else {
		s += z.Mixer.Msgsize()
	}
	s += 7
	if z.Mapper == nil {
		s += msgp.NilSize
	} else {
		s += 1 + 4 + msgp.Uint16Size + 5 + z.Mapper.Data.Msgsize()
	}
	return
}

