// DecodeMsg implements msgp.Decodable
func (z *PPUTileInfo) DecodeMsg(dc *msgp.Reader) (err error) {
	var field []byte
	_ = field
	var zb0001 uint32
	zb0001, err = dc.ReadMapHeader()
	if err != nil {
		err = msgp.WrapError(err)
		return
	}
	for zb0001 > 0 {
		zb0001--
		field, err = dc.ReadMapKeyPtr()
		if err != nil {
			err = msgp.WrapError(err)
			return
		}
		switch msgp.UnsafeString(field) {
		case "LowByte":
			z.LowByte, err = dc.ReadUint8()
			if err != nil {
				err = msgp.WrapError(err, "LowByte")
				return
			}
		case "HighByte":
			z.HighByte, err = dc.ReadUint8()
			if err != nil {
				err = msgp.WrapError(err, "HighByte")
				return
			}
		case "PaletteOffset":
			z.PaletteOffset, err = dc.ReadUint8()
			if err != nil {
				err = msgp.WrapError(err, "PaletteOffset")
				return
			}
		case "TileAddr":
			z.TileAddr, err = dc.ReadUint16()
			if err != nil {
				err = msgp.WrapError(err, "TileAddr")
				return
			}
		default:
			err = dc.Skip()
			if err != nil {
				err = msgp.WrapError(err)
				return
			}
		}
	}
	return
}

